const res = pm.response.json();
if (res._lab && res._lab.requestId) pm.environment.set("last_test_id", res._lab.requestId.slice(-6));

// ==========================================
// CONFIGURATION (টেস্ট অনুযায়ী এই ২টি ভ্যালু চেঞ্জ করবেন)
// ==========================================
const expectedStatus = 201; // যেমন: 200, 201, 400, 401, 403, 409
const expectedMessage = ""; // Error মেসেজের অংশ বা Success এর কোনো স্পেসিফিক টেক্সট (ফাঁকা রাখলে চেক করবে না)

// ==========================================
// 1. STATUS CODE TEST
// ==========================================
pm.test(`Status code is ${expectedStatus}`, function () {
    pm.response.to.have.status(expectedStatus);
});

// ==========================================
// 2. ERROR / RESPONSE MESSAGE TEST
// ==========================================
if (expectedMessage && expectedMessage.trim() !== "") {
    pm.test(`Response contains expected message: "${expectedMessage}"`, function () {
        const res = pm.response.json();

        // Response এ error, message অথবা detail যেকোনো ফিল্ড থাকতে পারে
        const actualMessage = res.error || res.message || res.detail || JSON.stringify(res);

        pm.expect(actualMessage.toLowerCase()).to.include(expectedMessage.toLowerCase());
    });
}

// ==========================================
// 3. ENVIRONMENT VARIABLES & LAB ID SAVING
// ==========================================
try {
    const res = pm.response.json();
    if (res && res._lab && res._lab.requestId) {
        const fullRequestId = res._lab.requestId;
        const shortTestId = fullRequestId.slice(-6); // শেষ ৬ ডিজিট কেটে নেয়া

        pm.environment.set("last_request_id", fullRequestId);
        pm.environment.set("last_test_id", shortTestId);

        console.log(`[SAVED] last_request_id: ${fullRequestId}`);
        console.log(`[SAVED] last_test_id: ${shortTestId}`);
    }
} catch (e) {
    // JSON পার্স না হলেও যেন স্ক্রিপ্ট ফেল না করে
    console.log("Response body is not a valid JSON or missing _lab properties.");
}

